taken_players = []
espn_roster = Roster("ESPN")
fred_roster = Roster("FRED")

ALG_TYPE = AlgorithmType.TRAIN

rounds = 1
#snake draft like normal fantasy football
while rounds <= 6:
    print(f"Round {rounds}")
    #I gave ESPN first pick
    if rounds % 2 == 1:
        espn_drafted_player, espn_drafted_position = espn_drafter.draft_player_espn(ELIGIBLE_PLAYERS_LIST, espn_roster, taken_players)
        taken_players.append(espn_drafted_player)
        espn_roster.addPlayer(espn_drafted_player, espn_drafted_position)
        print(f"ESPN takes {espn_drafted_player}, {espn_drafted_position}")
        
        fred_drafted_player, fred_drafted_position = draft_player_fred(ELIGIBLE_PLAYERS_LIST, fred_roster, taken_players, ALG_TYPE)
        taken_players.append(fred_drafted_player)
        fred_roster.addPlayer(fred_drafted_player, fred_drafted_position)
        print(f"FRED takes {fred_drafted_player}, {fred_drafted_position}")
    else:
        fred_drafted_player, fred_drafted_position = draft_player_fred(ELIGIBLE_PLAYERS_LIST, fred_roster, taken_players, ALG_TYPE)
        taken_players.append(fred_drafted_player)
        fred_roster.addPlayer(fred_drafted_player, fred_drafted_position)
        print(f"FRED takes {fred_drafted_player}, {fred_drafted_position}")
        
        espn_drafted_player, espn_drafted_position = espn_drafter.draft_player_espn(ELIGIBLE_PLAYERS_LIST, espn_roster, taken_players)
        taken_players.append(espn_drafted_player)
        espn_roster.addPlayer(espn_drafted_player, espn_drafted_position)
        print(f"ESPN takes {espn_drafted_player}, {espn_drafted_position}")
    rounds += 1

espn_roster.printRoster()
fred_roster.printRoster()

print("Beginning 2025 season simulation!")
week = 1
while week <= 18:
    espn_score, fred_score = simulate_week(espn_roster, fred_roster, week)
    print(f"Week {week}: {espn_score}-{fred_score}")
    week += 1

print("Final Standings:")
print(f"ESPN:")
espn_roster.printRecord()
print(f"FRED:")
fred_roster.printRecord()